import json

path = r"C:\Users\user\.claude\projects\C--Users-user-Desktop-Git-deep-learning-team-project-data-pre\548e63c0-c66d-4fd4-8fe0-f534715e4349.jsonl"
out_lines = []

with open(path, "r", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        typ = obj.get("type")
        if typ not in ("user", "assistant"):
            continue
        msg = obj.get("message", {})
        role = msg.get("role", typ)
        content = msg.get("content")
        texts = []
        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for block in content:
                if not isinstance(block, dict):
                    continue
                btype = block.get("type")
                if btype == "text":
                    texts.append(block.get("text", ""))
                elif btype == "tool_use":
                    texts.append(f"[TOOL_USE: {block.get('name')}]")
                elif btype == "tool_result":
                    c = block.get("content")
                    if isinstance(c, list):
                        for cc in c:
                            if isinstance(cc, dict) and cc.get("type") == "text":
                                t = cc.get("text", "")
                                texts.append(f"[TOOL_RESULT: {t[:200]}]")
                    elif isinstance(c, str):
                        texts.append(f"[TOOL_RESULT: {c[:200]}]")
        joined = "\n".join(t for t in texts if t and not t.startswith("[TOOL"))
        if joined.strip():
            out_lines.append(f"=== {role.upper()} ===\n{joined}\n")

with open(r"C:\Users\user\AppData\Local\Temp\claude\C--Users-user-Desktop-Git-deep-learning-team-project-data-pre\83b03b51-f92c-44d6-bd28-8cb6068b1224\scratchpad\session_dump.txt", "w", encoding="utf-8") as f:
    f.write("\n".join(out_lines))

print("total entries:", len(out_lines))

